import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"This session's plan — one page","description":"","frontmatter":{},"headers":[],"relativePath":"graphopt/project/reports/2026-10-27-session-plan.md","filePath":"vendored/graphopt/project/reports/2026-10-27-session-plan.md"}`),a={name:`graphopt/project/reports/2026-10-27-session-plan.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="this-session-s-plan-—-one-page" tabindex="-1">This session&#39;s plan — one page <a class="header-anchor" href="#this-session-s-plan-—-one-page" aria-label="Permalink to “This session&#39;s plan — one page”">​</a></h1><p><strong>Goal:</strong> make the machine find the kernel instead of me. Today I wrote it; the machine only tuned 48 settings of my design.</p><p><strong>Baseline already proven</strong> (no new work needed): our int4 GEMV is <strong>2.96× / 1.52× / 1.35×</strong> over <code>awq_gemm</code> on three of four layer shapes, cold and exact; dropped into vLLM it is <strong>token-identical and 29.2 % faster</strong>. Everything below is about making that automatic.</p><h2 id="phases" tabindex="-1">Phases <a class="header-anchor" href="#phases" aria-label="Permalink to “Phases”">​</a></h2><table tabindex="0"><thead><tr><th>phase</th><th>work</th><th>gate</th><th>if it fails</th></tr></thead><tbody><tr><td><strong>M1a</strong></td><td>ADR-0160 — the IR is <code>Term</code> + kit-declared ops</td><td>accepted</td><td>stop; nothing builds on sand</td></tr><tr><td><strong>M1b</strong></td><td><code>lib-kernel-ir</code> (public) — nine ops: signature, grade, cost, torch denotation</td><td>every op has all four</td><td>IR is not expressive enough — finding about the calculus</td></tr><tr><td><strong>M1c</strong></td><td>equality gate vs <code>awq_gemm</code> in <code>graphopt/bench</code></td><td>cosine ≥ 0.9999, inside the timing path</td><td>fix the gate before any codegen</td></tr><tr><td><strong>M1d</strong></td><td><code>compile-triton</code> (Rust) — <code>Term</code> → Triton, <code>qgemv</code> + <code>gate_proj</code>, 4 <code>split_k</code> each</td><td>8 variants compile, run, and pass the gate</td><td><strong>kill:</strong> if generated code can&#39;t match hand-written Triton, keep hand-writing</td></tr><tr><td><strong>M1e</strong></td><td>search driver in <code>opt-kernel</code></td><td>emits best kernel per shape + routing row</td><td>search has no objective</td></tr><tr><td><strong>M1.5</strong></td><td>compile cache + roofline pruning</td><td>1 in 10 candidates ever compiled</td><td>breadth is rate-limited by <code>triton.jit</code></td></tr><tr><td><strong>M2</strong></td><td><code>lib-triton</code> binding + <code>kit-kernel-ir</code></td><td>a found kernel runs in a host</td><td>—</td></tr><tr><td><strong>M3</strong></td><td>breadth: GPTQ/FP8, more shapes</td><td>routing table with no hand entries</td><td>—</td></tr><tr><td><strong>M4</strong></td><td>dissolve into <code>ext-opt-*</code> (ADR-0159 triggers)</td><td>a non-researcher caller</td><td>—</td></tr></tbody></table><h2 id="order-with-dependencies" tabindex="-1">Order, with dependencies <a class="header-anchor" href="#order-with-dependencies" aria-label="Permalink to “Order, with dependencies”">​</a></h2><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>ADR-0160 ─▶ lib-kernel-ir ─▶ equality gate ─▶ compile-triton ─▶ search ─▶ M1 gate</span></span>
<span class="line"><span>                    └─────────── denotations are the gate&#39;s reference ────┘</span></span></code></pre></div><p>The gate comes <strong>before</strong> the lowerer on purpose: three fake results this week came from checking against my own reimplementation, or checking nothing.</p><h2 id="decisions-already-made" tabindex="-1">Decisions already made <a class="header-anchor" href="#decisions-already-made" aria-label="Permalink to “Decisions already made”">​</a></h2><ul><li><strong>Lab-form</strong> (ADR-0159): repos and drivers, no <code>ext</code> wrapper, no FFI, until three triggers fire.</li><li><strong>Naming:</strong> <code>opt-graph</code> (today <code>graphopt</code>), <code>opt-kernel</code> (today <code>kernelopt</code>); third member only on the rule of three.</li><li><strong>Visibility</strong> (ADR-0150): <code>lib-kernel-ir</code> public — the vocabulary is the public artefact; <code>compile-triton</code>, the binding and any <code>ext</code> stay private until done.</li><li><strong>The IR is <code>Term</code></strong> — no new schema; the six combinators stay closed.</li><li><strong>Triton first</strong>, CUTLASS only on a measured gap.</li></ul><h2 id="needs-you" tabindex="-1">Needs you <a class="header-anchor" href="#needs-you" aria-label="Permalink to “Needs you”">​</a></h2><ol><li><strong>Repo creation</strong>: <code>lib-kernel-ir</code>, <code>compile-triton</code> (say go, or create them and I fill them).</li><li><strong>Repo ownership</strong> for this session, so we don&#39;t overwrite each other.</li><li><strong>GPU window</strong> — I stay off it while you benchmark.</li><li><strong>ADR-0160 acceptance</strong> — the decision should carry your name.</li></ol>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};